    // 16-bit ALU with synchronous reset and registered outputs
// Supports: ADD, SUB, AND, OR, XOR, SLL, SRL, SRA, SLT, SLTU
module alu_16bit (
    input wire clk,
    input wire rst,
    input wire [15:0] a,
    input wire [15:0] b,
    input wire [3:0] opcode,
    output reg [15:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Internal signals for combinational logic
    reg [15:0] temp_result;
    reg temp_overflow;

    // Combinational logic for ALU operations
    always @(*) begin
        temp_overflow = 1'b0;
        temp_result = 16'b0;
        
        case (opcode)
            4'b0000: begin // ADD: A + B
                temp_result = a + b;
                // Overflow occurs when operands have same sign but result has different sign
                temp_overflow = (a[15] & b[15] & ~temp_result[15]) |
                                (~a[15] & ~b[15] & temp_result[15]);
            end
            4'b0001: begin // SUB: A - B
                temp_result = a - b;
                // Overflow occurs when A and B have different signs and result sign differs from A
                temp_overflow = (a[15] & ~b[15] & ~temp_result[15]) |
                                (~a[15] & b[15] & temp_result[15]);
            end
            4'b0010: temp_result = a & b;  // AND
            4'b0011: temp_result = a | b;  // OR
            4'b0100: temp_result = a ^ b;  // XOR
            4'b0101: begin // SLL: Logical left shift
                // Shift amount is lower 4 bits of B (since 2^4 = 16, max shift is 15)
                integer i;
                temp_result = a;
                for (i = 0; i < 4; i = i + 1) begin
                    if (b[i]) begin
                        temp_result = temp_result << (1 << i);
                    end
                end
            end
            4'b0110: begin // SRL: Logical right shift (zero-filled)
                integer i;
                temp_result = a;
                for (i = 0; i < 4; i = i + 1) begin
                    if (b[i]) begin
                        temp_result = temp_result >> (1 << i);
                    end
                end
            end
            4'b0111: begin // SRA: Arithmetic right shift (sign-extended)
                integer i;
                reg [15:0] shifted;
                shifted = a;
                for (i = 0; i < 4; i = i + 1) begin
                    if (b[i]) begin
                        shifted = shifted >>> (1 << i);
                    end
                end
                temp_result = shifted;
            end
            4'b1000: begin // SLT: Signed set-less-than (A < B, signed comparison)
                if (a < b) begin
                    temp_result = 16'b1;
                end else begin
                    temp_result = 16'b0;
                end
                temp_overflow = 1'b0; // No overflow for comparison
            end
            4'b1001: begin // SLTU: Unsigned set-less-than (A < B, unsigned comparison)
                if ({1'b0, a} < {1'b0, b}) begin
                    temp_result = 16'b1;
                end else begin
                    temp_result = 16'b0;
                end
                temp_overflow = 1'b0; // No overflow for comparison
            end
            default: temp_result = 16'b0;
        endcase
    end

    // Sequential logic for output registers
    always @(posedge clk) begin
        if (rst) begin
            result <= 16'b0;
            zero <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result <= temp_result;
            zero <= (temp_result == 16'b0);
            overflow <= temp_overflow;
            negative <= temp_result[15];
        end
    end

endmodule